You can simulate a server error by mocking the `requests` call and returning a manually constructed `requests.Response` with a `5xx` status code, such as `500`.

```python
import unittest
from unittest.mock import patch
import requests


def fetch_user(user_id):
    response = requests.get(f"https://example.com/users/{user_id}")
    response.raise_for_status()
    return response.json()


def make_response(status_code, json_data=None, text=""):
    response = requests.Response()
    response.status_code = status_code
    response._content = (
        requests.models.complexjson.dumps(json_data).encode("utf-8")
        if json_data is not None
        else text.encode("utf-8")
    )
    response.headers["Content-Type"] = "application/json"
    response.url = "https://example.com/users/123"
    return response


class TestFetchUser(unittest.TestCase):
    @patch("requests.get")
    def test_server_error(self, mock_get):
        mock_get.return_value = make_response(
            500,
            {"error": "Internal Server Error"}
        )

        with self.assertRaises(requests.HTTPError) as exc:
            fetch_user(123)

        self.assertEqual(exc.exception.response.status_code, 500)
        mock_get.assert_called_once_with("https://example.com/users/123")


if __name__ == "__main__":
    unittest.main()
```

The key part is creating a `requests.Response`, setting `status_code = 500`, and then letting your production code call `raise_for_status()` so the test can verify the error handling path.

Use a thread pool: each worker fetches one URL with `requests`, and the main thread collects the results as they finish.

```python
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

urls = [
    "https://example.com",
    "https://httpbin.org/get",
    "https://httpbin.org/status/200",
]

def fetch_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()

        return {
            "url": url,
            "ok": True,
            "status_code": response.status_code,
            "text": response.text,
        }

    except requests.RequestException as e:
        return {
            "url": url,
            "ok": False,
            "error": str(e),
        }

results = []

with ThreadPoolExecutor(max_workers=10) as executor:
    futures = [executor.submit(fetch_url, url) for url in urls]

    for future in as_completed(futures):
        results.append(future.result())

for result in results:
    if result["ok"]:
        print(f'{result["url"]}: {result["status_code"]}, {len(result["text"])} bytes')
    else:
        print(f'{result["url"]}: ERROR - {result["error"]}')
```

`max_workers` controls how many requests run at the same time. For many URLs, choose a reasonable number like `10`, `20`, or `50` depending on the servers you are calling and your network limits.
